 function dither(c,w,h,cell,brightness){c.clearRect(0,0,w,h);for(let y=0,j=0;y<h;y+=cell,j++)for(let x=0,i=0;x<w;x+=cell,i++){const value=brightness(x/w,y/h,i,j);if(value<.035)continue;const threshold=noise(i,j);if(threshold>Math.min(1,value*1.7))continue;const color=Math.min(5,Math.max(0,Math.floor(value*5+threshold*.8)));c.fillStyle=palette[color];const size=cell*(.45+.26*Math.min(value,1));c.fillRect(x,y,size,size);}}
