 if(activeLens===1){const col=Math.floor(u*17),local=u*17-col;const height=.12+.65*Math.exp(-Math.pow((col-8)/4.2,2));if(u>.08&&u<.92&&local<.65&&z>.86-height&&z<.86)shape=col===8?1:.35+.35*(1-z);}
 if(activeLens===2&&u>.1&&u<.88&&z<.88){const curve=.86-Math.pow((u-.1)/.78,2)*.67;if(Math.abs(z-curve)<.018)shape=1;else if(z>curve)shape=.2;}
 if(activeLens===3&&u>.1&&u<.9){const curve=.28+.12*Math.sin(u*12)+Math.pow(u,2)*.55;if(Math.abs(z-curve)<.018)shape=.9;if(Math.abs(z-.78)<.009&&i%3)shape=.55;}
 if(activeLens===4&&u>.1&&u<.9&&z>.15&&z<.85){if(Math.abs(u-.1)<.02||Math.abs(u-.9)<.02||Math.abs(z-.15)<.02||Math.abs(z-.85)<.02)shape=.8;if(z<.29&&z>.24)shape=.35;if(u>.2&&u<.34&&z>.4&&z<.55)shape=.9;if(u>.42&&u<.8&&Math.abs(z-.46)<.025)shape=.5;if(u>.2&&u<.78&&Math.abs(z-.68)<.025)shape=.45;}
