 function ribbon(canvas,t,footer=false){const {ctx:c,w,h}=fitCanvas(canvas);dither(c,w,h,6.4,(x,y,i,j)=>{const distance=x-.5;const middle=footer?.91+.035*Math.sin(x*8+t*.35):1.28-2*distance*distance;const width=footer?.22:.09+Math.abs(distance)*.14;const off=(y-middle)/width;if(Math.abs(off)>1.6)return 0;const body=Math.max(0,1-Math.abs(off)*.6);const stripe=Math.exp(-Math.pow((off+.16+.18*Math.sin(x*6+t*.2))/.17,2));const fold=.5+.5*Math.sin(x*24-off*3+t*.7);return Math.min(1,body*(.08+fold*.22)+stripe*(.52+.48*fold));});}
 function horizon(canvas,t){const {ctx:c,w,h}=fitCanvas(canvas);dither(c,w,h,5.6,(x,y,i,j)=>{const yy=y-.45;const curve=.58+.05*Math.sin(x*7+t*.4);const intensity=Math.exp(-Math.pow((y-curve)/.24,2));return intensity*(.04+.28*Math.pow(Math.max(0,Math.cos(x*15+yy*8-t*.5)),3));});}
 function updateLaunch(){const p=launchProgress/100;const stage=Math.min(4,Math.floor(p*5));const phases=['Created','Trading','Threshold','Graduated','Market'];const desc=['Give your idea its first block. Name it, choose a ticker and prepare the details.','Buyers and sellers shape the curve. Net reserves determine the progress.','The curve reaches its provider-defined graduation threshold.','The venue migrates liquidity according to its published launch rules.','The token has a market. Check the pool and its actual liquidity rules.'];$('#launch-progress').value=String(launchProgress);$('#launch-percent').textContent=Math.floor(launchProgress)+'%';$('#reserve-value').textContent=Math.floor(launchProgress)+'%';$('#launch-phase').textContent=phases[stage];$('#phase-number').textContent='0'+(stage+1);$('#phase-description').textContent=desc[stage];$$('[data-stage]').forEach(b=>b.classList.toggle('active',Number(b.dataset.stage)===stage));const x=22+p*460,y=225-185*p*p;const points=Array.from({length:Math.max(2,Math.ceil(p*70))},(_,i)=>{const q=i/Math.max(1,Math.ceil(p*70)-1)*p;return `${22+q*460},${225-185*q*q}`;}).join(' ');$('#curve-chart').innerHTML=`<defs><pattern id="curve-dots" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="3" height="3" fill="#583091"/></pattern></defs><path d="M22 40H685" stroke="#7886a0" stroke-dasharray="4 6"/><text x="24" y="26" fill="#7c89a4" font-size="10" font-family="Geist Mono">GRADUATION THRESHOLD · ILLUSTRATION</text><path d="M22 225 ${points.split(' ').map(n=>'L'+n).join(' ')} L${x} 225Z" fill="url(#curve-dots)"/><polyline points="${points}" fill="none" stroke="#80f4c6" stroke-width="2"/><rect x="${x-3}" y="${y-3}" width="6" height="6" fill="#fff"/><path d="M22 226H482" stroke="#243455"/><text x="22" y="249" fill="#7c89a4" font-size="10" font-family="Geist Mono">First buy</text><text x="482" y="249" text-anchor="end" fill="#7c89a4" font-size="10" font-family="Geist Mono">Threshold</text><rect x="530" y="55" width="150" height="170" rx="6" fill="${stage>=3?'#201036':'#070b15'}" stroke="${stage>=3?'#14f195':'#243455'}"/><text x="605" y="86" text-anchor="middle" fill="#e4edff" font-size="14">Market pool</text><text x="605" y="106" text-anchor="middle" fill="#7c89a4" font-size="10">seeded by the curve</text>${Array.from({length:14},(_,i)=>`<rect x="${547+i*8}" y="${210-(18+Math.exp(-Math.pow((i-7)/4,2))*60)*(stage>=3?1:.2)}" width="5" height="${(18+Math.exp(-Math.pow((i-7)/4,2))*60)*(stage>=3?1:.2)}" fill="${i===7?'#e4ecff':'#9945ff'}"/>`).join('')}`;}
 $('#launch-play').addEventListener('click',()=>{launchRunning=!launchRunning;$('#launch-play').textContent=launchRunning?'Ⅱ':'▶';});$('#launch-progress').addEventListener('input',e=>{launchRunning=false;launchProgress=Number(e.target.value);$('#launch-play').textContent='▶';updateLaunch();});$$('[data-stage]').forEach(b=>b.addEventListener('click',()=>{launchRunning=false;launchProgress=Number(b.dataset.stage)*20+5;$('#launch-play').textContent='▶';updateLaunch();}));
 const presets=[{symbol:'SOL',side:'long',leverage:5},{symbol:'BTC',side:'long',leverage:3},{symbol:'ETH',side:'short',leverage:4},{symbol:'SOL',side:'long',leverage:2}];
 function updateReplay(){const config=presets[preset],market=getData()?.markets?.find(m=>m.symbol===config.symbol),candles=market?.candles||[];const n=Math.max(0,Math.floor(replayProgress/100*(candles.length-1)));const entry=candles[0]?.close,mark=candles[n]?.close;const pos=positionMath({entry,mark,margin:1000,leverage:config.leverage,side:config.side});$('#replay-progress').value=String(replayProgress);$('#replay-day').textContent=String(Math.floor(replayProgress/100*29)+1);$('#replay-size').textContent=(1000*config.leverage).toLocaleString()+' USDC';$('#replay-liq').textContent=pos?'$'+money(pos.liquidation):'—';const pnl=$('#replay-pnl');pnl.textContent=pos?(pos.liquidated?'Liquidation reached':(pos.pnl>=0?'+':'−')+money(Math.abs(pos.pnl))+' USDC'):'—';pnl.className=pos?(pos.pnl>=0?'good':'bad'):'';drawPriceChart($('#replay-chart'),candles,{entry,liquidation:pos?.liquidation,side:config.side,cursor:n});}
 $$('[data-preset]').forEach(b=>b.addEventListener('click',()=>{preset=Number(b.dataset.preset);replayProgress=0;$$('[data-preset]').forEach(el=>el.classList.toggle('active',el===b));updateReplay();}));$('#replay-play').addEventListener('click',()=>{replayRunning=!replayRunning;$('#replay-play').textContent=replayRunning?'Ⅱ':'▶';});$('#replay-progress').addEventListener('input',e=>{replayRunning=false;replayProgress=Number(e.target.value);$('#replay-play').textContent='▶';updateReplay();});
